public extension SRC721 {
    func deploy(privateKey: Data, name: String, symbol: String, baseURI: String, maxSupply: BigUInt, mintPrice: BigUInt) async throws -> [String] {
        var tempBaseURI = baseURI
        if !baseURI.isEmpty && baseURI.last != "/" {
            tempBaseURI.append("/")
        }
        return try await contract.deploy(privateKey: privateKey, bytecode: Data.fromHex(bytecode)!, parameters: [name, symbol, tempBaseURI, maxSupply, mintPrice])
    }

    func mint(privateKey: Data, value: BigUInt, to: EthereumAddress, amount: BigUInt) async throws -> String {
        return try await contract.call(privateKey: privateKey, value: value, method: "mint", parameters: [to, amount])
    }

    func adminMint(privateKey: Data, to: EthereumAddress, amount: BigUInt) async throws -> String {
        return try await contract.call(privateKey: privateKey, method: "adminMint", parameters: [to, amount])
    }

    func withdraw(privateKey: Data) async throws -> String {
        return try await contract.call(privateKey: privateKey, method: "withdraw")
    }

    func approve(privateKey: Data, to: EthereumAddress, tokenId: BigUInt) async throws -> String {
        return try await contract.call(privateKey: privateKey, method: "approve", parameters: [to, tokenId])
    }

    func safeTransferFrom(privateKey: Data, from: EthereumAddress, to: EthereumAddress, tokenId: BigUInt) async throws -> String {
        return try await contract.call(privateKey: privateKey, method: "safeTransferFrom", parameters: [from, to, tokenId])
    }

    func setBaseURI(privateKey: Data, baseURI: String) async throws -> String {
        var tempBaseURI = baseURI
        if !baseURI.isEmpty && baseURI.last != "/" {
            tempBaseURI.append("/")
        }
        return try await contract.call(privateKey: privateKey, method: "setBaseURI", parameters: [tempBaseURI])
    }

    func setMintPrice(privateKey: Data, mintPrice: BigUInt) async throws -> String {
        return try await contract.call(privateKey: privateKey, method: "setMintPrice", parameters: [mintPrice])
    }

    func setMaxSupply(privateKey: Data, maxSupply: BigUInt) async throws -> String {
        return try await contract.call(privateKey: privateKey, method: "setMaxSupply", parameters: [maxSupply])
    }

    func setAllowList(privateKey: Data, addresses: [EthereumAddress], amounts: [BigUInt]) async throws -> String {
        return try await contract.call(privateKey: privateKey, method: "setAllowList", parameters: [addresses, amounts])
    }

    func owner() async throws -> EthereumAddress {
        return try await contract.query("owner", outType: EthereumAddress.self)
    }

    func name() async throws -> String {
        return try await contract.query("name", outType: String.self)
    }

    func symbol() async throws -> String {
        return try await contract.query("symbol", outType: String.self)
    }

    func baseURI() async throws -> String {
        return try await contract.query("baseURI", outType: String.self)
    }

    func mintPrice() async throws -> BigUInt {
        return try await contract.query("mintPrice", outType: BigUInt.self)
    }

    func maxSupply() async throws -> BigUInt {
        return try await contract.query("maxSupply", outType: BigUInt.self)
    }

    func totalSupply() async throws -> BigUInt {
        return try await contract.query("totalSupply", outType: BigUInt.self)
    }

    func remainSupply() async throws -> BigUInt {
        return try await contract.query("remainSupply", outType: BigUInt.self)
    }

    func balanceOf(addr: EthereumAddress) async throws -> BigUInt {
        return try await contract.query("balanceOf", parameters: [addr], outType: BigUInt.self)
    }

    func ownerOf(tokenId: BigUInt) async throws -> EthereumAddress {
        return try await contract.query("ownerOf", parameters: [tokenId], outType: EthereumAddress.self)
    }

    func tokenByIndex(index: BigUInt) async throws -> BigUInt {
        return try await contract.query("tokenByIndex", parameters: [index], outType: BigUInt.self)
    }

    func tokenOfOwnerByIndex(owner: EthereumAddress, index: BigUInt) async throws -> BigUInt {
        return try await contract.query("tokenOfOwnerByIndex", parameters: [owner, index], outType: BigUInt.self)
    }

    func getAllowAddrNum() async throws -> BigUInt {
        return try await contract.query("getAllowAddrNum", parameters: [], outType: BigUInt.self)
    }

    func getAllowAddrs(_ start: BigUInt, _ count: BigUInt) async throws -> AllowInfo {
        return try await contract.queryStruct("getAllowAddrs", parameters: [start, count], outType: AllowInfo.self)
    }

    func amountAllowToMint(addr: EthereumAddress) async throws -> BigUInt {
        return try await contract.query("amountAllowToMint", parameters: [addr], outType: BigUInt.self)
    }

    func canMint(addr: EthereumAddress) async throws -> Bool {
        return try await contract.query("canMint", parameters: [addr], outType: Bool.self)
    }

    func mintedTotal() async throws -> BigUInt {
        return try await contract.query("mintedTotal", outType: BigUInt.self)
    }

    func getApproved(tokenId: BigUInt) async throws -> EthereumAddress {
        return try await contract.query("getApproved", parameters: [tokenId], outType: EthereumAddress.self)
    }

    func tokenURI(tokenId: BigUInt) async throws -> String {
        return try await contract.query("tokenURI", parameters: [tokenId], outType: String.self)
    }

    func setOrgName(privateKey: Data, orgName: String) async throws -> String {
        return try await contract.call(privateKey: privateKey, method: "setOrgName", parameters: [orgName])
    }

    func setLogo(privateKey: Data, logo: Data) async throws -> String {
        if logo.count > 128 * 1024 {
            throw Web3Error.inputError(desc: "oversize logo, max size: 128 KB")
        }
        return try await contract.call(privateKey: privateKey, value: getLogoPayAmount(), method: "setLogo", parameters: [logo])
    }

    func setDescription(privateKey: Data, description: String) async throws -> String {
        return try await contract.call(privateKey: privateKey, method: "setDescription", parameters: [description])
    }

    func setOfficialUrl(privateKey: Data, officialUrl: String) async throws -> String {
        return try await contract.call(privateKey: privateKey, method: "setOfficialUrl", parameters: [officialUrl])
    }

    func setWhitePaperUrl(privateKey: Data, whitePaperUrl: String) async throws -> String {
        return try await contract.call(privateKey: privateKey, method: "setWhitePaperUrl", parameters: [whitePaperUrl])
    }

    func orgName() async throws -> String {
        return try await contract.query("orgName", outType: String.self)
    }

    func logo() async throws -> Data {
        return try await contract.query("logo", outType: Data.self)
    }

    func description() async throws -> String {
        return try await contract.query("description", outType: String.self)
    }

    func officialUrl() async throws -> String {
        return try await contract.query("officialUrl", outType: String.self)
    }

    func whitePaperUrl() async throws -> String {
        return try await contract.query("whitePaperUrl", outType: String.self)
    }

    func version() async throws -> String {
        return try await contract.query("version", outType: String.self)
    }

    func getLogoPayAmount() async throws -> BigUInt {
        return try await contract.query("getLogoPayAmount", outType: BigUInt.self)
    }

    func getLogoPayAddress() async throws -> EthereumAddress {
        return try await contract.query("getLogoPayAddress", outType: EthereumAddress.self)
    }
}
